mapper.select:
SELECT


, COALESCE(r.user_name, u.nickname) AS user_name
, COALESCE(r.mobile, u.mobile) AS mobile
, au.nickname AS auditorName
FROM sys_refund r
LEFT JOIN sys_user u ON u.id = r.user_id
LEFT JOIN sys_user au ON au.id = r.auditor_id


    AND r.is_deleted = 0

        AND r.refund_no LIKE CONCAT('%', #{query.refundNo}, '%')


        AND r.order_id = #{query.orderId}


        AND r.order_no LIKE CONCAT('%', #{query.orderNo}, '%')


        AND r.user_id = #{query.userId}



        AND COALESCE(r.user_name, u.nickname) LIKE CONCAT('%', #{query.userName}, '%')


        AND COALESCE(r.mobile, u.mobile) LIKE CONCAT('%', #{query.mobile}, '%')



        AND r.refund_type = #{query.refundType}


        AND r.status = #{query.status}


        AND r.refund_channel = #{query.refundChannel}


        AND r.third_refund_no = #{query.thirdRefundNo}



        AND r.apply_time >= #{query.beginTime}


        AND r.apply_time <= #{query.endTime}



        AND r.id IN

            #{id}



ORDER BY r.create_time DESC, r.id DESC
